@extends('layouts.app')@section('title','Sales')@section('content')<div class='title-row'><h1>Sales</h1><a class='btn' href='{{ route('sales.create') }}'>Record sale</a></div><div class='card'><table class='table'><tr><th>Product</th><th>Qty</th><th>Unit</th><th>Total</th><th>Sold</th><th></th></tr>@forelse($sales as $sale)<tr><td>{{ $sale->product->name }}</td><td>{{ $sale->quantity }}</td><td>{{ number_format((float)$sale->unit_price,2) }}</td><td>{{ number_format($sale->quantity*(float)$sale->unit_price,2) }}</td><td>{{ $sale->sold_at->format('M j, Y H:i') }}</td><td><form method='post' action='{{ route('sales.destroy',$sale) }}'>@csrf @method('delete')<button>Remove</button></form></td></tr>@empty<tr><td colspan='6'>No sales recorded.</td></tr>@endforelse</table>{{ $sales->links() }}</div>@endsection